# Use node with built-in zlib to read docx
cd /workspace/testbed/docs && node -e "
const fs = require('fs');
const zlib = require('zlib');
const path = require('path');

// docx is a zip file, let's parse it manually
const files = fs.readdirSync('.').filter(f => f.endsWith('.docx'));

for (const fname of files) {
    const buf = fs.readFileSync(fname);
    // Read zip entries manually
    // Find end of central directory
    let eocdPos = -1;
    for (let i = buf.length - 22; i >= 0; i--) {
        if (buf.readUInt32LE(i) === 0x06054b50) { eocdPos = i; break; }
    }
    if (eocdPos < 0) { console.log('=== ' + fname + ' === NOT A VALID ZIP'); continue; }

    const cdOffset = buf.readUInt32LE(eocdPos + 16);
    const cdEntries = buf.readUInt16LE(eocdPos + 10);

    let pos = cdOffset;
    let documentXml = null;
    for (let i = 0; i < cdEntries; i++) {
        if (buf.readUInt32LE(pos) !== 0x02014b50) break;
        const compMethod = buf.readUInt16LE(pos + 10);
        const compSize = buf.readUInt32LE(pos + 20);
        const uncompSize = buf.readUInt32LE(pos + 24);
        const nameLen = buf.readUInt16LE(pos + 28);
        const extraLen = buf.readUInt16LE(pos + 30);
        const commentLen = buf.readUInt16LE(pos + 32);
        const localOffset = buf.readUInt32LE(pos + 42);
        const entryName = buf.toString('utf8', pos + 46, pos + 46 + nameLen);

        if (entryName === 'word/document.xml') {
            // Read local file header
            const lhPos = localOffset;
            const lhNameLen = buf.readUInt16LE(lhPos + 26);
            const lhExtraLen = buf.readUInt16LE(lhPos + 28);
            const dataStart = lhPos + 30 + lhNameLen + lhExtraLen;
            const compData = buf.slice(dataStart, dataStart + compSize);

            if (compMethod === 8) {
                documentXml = zlib.inflateRawSync(compData).toString('utf8');
            } else {
                documentXml = compData.toString('utf8');
            }
        }

        pos += 46 + nameLen + extraLen + commentLen;
    }

    console.log('=== ' + fname + ' ===');
    if (documentXml) {
        const text = documentXml.replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ').trim();
        console.log(text.substring(0, 800));
    } else {
        console.log('(no word/document.xml found)');
    }
    console.log();
}
"

cd /workspace/testbed/docs && node -e "
const fs = require('fs');
const zlib = require('zlib');

const buf = fs.readFileSync('customer_report.docx');

let eocdPos = -1;
for (let i = buf.length - 22; i >= 0; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocdPos = i; break; }
}

const cdOffset = buf.readUInt32LE(eocdPos + 16);
const cdEntries = buf.readUInt16LE(eocdPos + 10);

let pos = cdOffset;
for (let i = 0; i < cdEntries; i++) {
    const compMethod = buf.readUInt16LE(pos + 10);
    const compSize = buf.readUInt32LE(pos + 20);
    const nameLen = buf.readUInt16LE(pos + 28);
    const extraLen = buf.readUInt16LE(pos + 30);
    const commentLen = buf.readUInt16LE(pos + 32);
    const localOffset = buf.readUInt32LE(pos + 42);
    const entryName = buf.toString('utf8', pos + 46, pos + 46 + nameLen);

    if (entryName === 'word/document.xml') {
        const lhPos = localOffset;
        const lhNameLen = buf.readUInt16LE(lhPos + 26);
        const lhExtraLen = buf.readUInt16LE(lhPos + 28);
        const dataStart = lhPos + 30 + lhNameLen + lhExtraLen;
        const compData = buf.slice(dataStart, dataStart + compSize);
        let xml;
        if (compMethod === 8) {
            xml = zlib.inflateRawSync(compData).toString('utf8');
        } else {
            xml = compData.toString('utf8');
        }

        // Parse paragraphs: each <w:p> becomes a line, each <w:t> is text
        const lines = [];
        const pRegex = /<w:p[ >][\s\S]*?<\/w:p>/g;
        let match;
        while ((match = pRegex.exec(xml)) !== null) {
            const pXml = match[0];
            const texts = [];
            const tRegex = /<w:t[^>]*>([^<]*)<\/w:t>/g;
            let tm;
            while ((tm = tRegex.exec(pXml)) !== null) {
                texts.push(tm[1]);
            }
            lines.push(texts.join(''));
        }
        console.log(lines.join('\n'));
        break;
    }

    pos += 46 + nameLen + extraLen + commentLen;
}
"

cd /workspace && node -e "
const PDFDocument = require('pdfkit');
const fs = require('fs');

const doc = new PDFDocument({ margin: 50, size: 'A4' });
const stream = fs.createWriteStream('testbed/docs/Maya_Chen_Customer_Activity_Report.pdf');
doc.pipe(stream);

// Title
doc.fontSize(20).font('Helvetica-Bold').text('Customer Activity Report', { align: 'center' });
doc.moveDown(0.5);

// Customer info
doc.fontSize(16).font('Helvetica-Bold').text('Maya Chen');
doc.moveDown(0.3);
doc.fontSize(10).font('Helvetica')
   .text('Email: maya.chen@example.com    |    Loyalty Tier: Gold    |    Store Credit: \$0');
doc.moveDown(0.5);

// Divider
doc.moveTo(50, doc.y).lineTo(545, doc.y).strokeColor('#cccccc').stroke();
doc.moveDown(0.5);

// Orders
const orders = [
  { id: 'ORD-6C71B1', date: '2026-09-02', status: 'Cancelled', total: '\$79',  items: 'Anker Portable Bluetooth Speaker' },
  { id: 'ORD-5B048F', date: '2026-09-02', status: 'Confirmed', total: '\$108', items: 'Anker Portable Bluetooth Speaker, LogiTech Wireless Mouse M310' },
  { id: 'ORD-12AAA3', date: '2026-09-02', status: 'Cancelled', total: '\$39',  items: 'Wireless Ergonomic Mouse' },
  { id: 'ORD-542FDA', date: '2026-09-02', status: 'Confirmed', total: '\$68',  items: 'OXO SoftWorks 3-Piece Mixing Bowl Set, ThermoPro Digital Meat Thermometer' },
  { id: 'ORD-D7E869', date: '2026-09-02', status: 'Confirmed', total: '\$71',  items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set' },
  { id: 'ORD-C31654', date: '2026-09-02', status: 'Confirmed', total: '\$29',  items: 'Wireless Mouse' },
  { id: 'ORD-CCC96C', date: '2026-09-02', status: 'Confirmed', total: '\$201', items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set, Aurora Smart Desk Lamp Pro' },
];

// Table header
const colX = { id: 50, date: 148, status: 228, total: 308, items: 365 };
const colW = { id: 95, date: 78, status: 78, total: 55, items: 180 };

doc.fontSize(9).font('Helvetica-Bold');
doc.text('Order ID',  colX.id,     doc.y, { width: colW.id });
const headerY = doc.y - 11;
doc.text('Date',      colX.date,   headerY, { width: colW.date });
doc.text('Status',    colX.status, headerY, { width: colW.status });
doc.text('Total',     colX.total,  headerY, { width: colW.total });
doc.text('Items',     colX.items,  headerY, { width: colW.items });
doc.moveDown(0.3);

// Header underline
doc.moveTo(50, doc.y).lineTo(545, doc.y).strokeColor('#999999').stroke();
doc.moveDown(0.3);

// Table rows
doc.font('Helvetica').fontSize(9);
orders.forEach((o, i) => {
    const bgY = doc.y - 2;
    if (i % 2 === 0) {
        doc.save().rect(48, bgY, 499, 26).fillColor('#f5f5f5').fill().restore();
    }

    const statusColor = o.status === 'Confirmed' ? '#2e7d32' : '#c62828';

    const rowY = doc.y;
    doc.fillColor('#333333').text(o.id,    colX.id,     rowY, { width: colW.id });
    doc.fillColor('#333333').text(o.date,  colX.date,   rowY, { width: colW.date });
    doc.fillColor(statusColor).text(o.status, colX.status, rowY, { width: colW.status });
    doc.fillColor('#333333').text(o.total, colX.total,  rowY, { width: colW.total, align: 'right' });
    doc.fillColor('#333333').text(o.items, colX.items,  rowY, { width: colW.items });
    doc.moveDown(0.6);
});

// Summary
doc.moveDown(0.5);
doc.moveTo(50, doc.y).lineTo(545, doc.y).strokeColor('#cccccc').stroke();
doc.moveDown(0.5);
doc.fillColor('#333333').fontSize(10).font('Helvetica-Bold')
   .text('Summary: ', { continued: true })
   .font('Helvetica')
   .text('7 total orders  —  5 confirmed  —  2 cancelled  —  All placed on 2026-09-02');

doc.end();

stream.on('finish', () => {
    const stats = fs.statSync('testbed/docs/Maya_Chen_Customer_Activity_Report.pdf');
    console.log('PDF created successfully: testbed/docs/Maya_Chen_Customer_Activity_Report.pdf');
    console.log('File size: ' + (stats.size / 1024).toFixed(1) + ' KB');
});
"
